#!/usr/bin/env python3
"""Query an index generated by import.py. Rankings use approximate arithmetic."""
import argparse
import cmath
from fractions import Fraction
import importlib.util
import json
import math
from pathlib import Path

spec = importlib.util.spec_from_file_location('atlas_import', Path(__file__).with_name('import.py'))
atlas = importlib.util.module_from_spec(spec)
spec.loader.exec_module(atlas)


def numeric(value):
    terms = atlas.parse_expression(value)
    values = [complex(Fraction(a, b)) * cmath.exp(2j * math.pi * float(Fraction(p, q))) for a, b, p, q in terms]
    return complex(math.fsum(x.real for x in values), math.fsum(x.imag for x in values))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('query', choices=['weakly-integral', 'no-known-cs', 'not-cs', 'max-dimension'])
    parser.add_argument('--index', type=Path, default=Path('data/generated/index.json'))
    parser.add_argument('--kind', choices=['bosonic', 'fermionic'])
    parser.add_argument('--positive-only', action='store_true', help='restrict to the Atlas pseudo-unitary flag')
    args = parser.parse_args()
    index = json.loads(args.index.read_text())
    rows = [r for r in index['records'] if (args.kind is None or r['kind'] == args.kind) and (not args.positive_only or r['positiveDimensions'] is True)]
    if args.query == 'weakly-integral':
        result = [r for r in rows if r['weaklyIntegral'] is True]
    elif args.query in ('no-known-cs', 'not-cs'):
        # A rejection is distinguished from absent evidence; records with a known
        # Tannakian extension are not labeled Not CS by the Atlas.
        def is_not_cs(r):
            eligible = r['chernSimonsEligibility']
            ext = any(x.get('tannakianExtensionDependency') for x in r['realizations'])
            return eligible is not None and eligible.get('eligible') is False and not ext
        def has_cs_label(r):
            cs_types = {'lie', 'abelian', 'product', 'condensation', 'fermionic-condensation', 'product-condensation'}
            return (any(x.get('type') in cs_types or (x.get('type') == 'gauging' and x.get('tannakianExtensionDependency')) for x in r['realizations']) or bool(r['knownProductRealization'])) and not is_not_cs(r)
        result = [r for r in rows if is_not_cs(r) if args.query == 'not-cs'] if args.query == 'not-cs' else [r for r in rows if not has_cs_label(r)]
    else:
        best = {}
        for r in rows:
            dims = [numeric(x) for x in r['quantumDimensions']]
            val = sum(x*x for x in dims)
            if abs(val.imag) > 1e-6 * max(1, abs(val.real)):
                raise ValueError(f"{r['id']}: non-real global dimension")
            key = (r['kind'], r['rank'])
            if key not in best or val.real > best[key][0]:
                best[key] = (val.real, r)
        result = [{'approxGlobalDimensionSquared': value, **row} for _, (value, row) in sorted(best.items())]
    print(json.dumps({'sourceFingerprint': index['sourceFingerprint'], 'query': args.query, 'count': len(result), 'records': result}, indent=2))


if __name__ == '__main__':
    main()
